SELECT SANCTIONS_ID, USER_ID, SANCTIONS_TYPES, SANCTIONS_START_DATE, SANCTIONS_END_DATE, SANCTIONS_REASON, ADMIN_ACCOUNT_ID, SANCTIONS_CREATED_AT
FROM sanctions
WHERE SANCTIONS_ID = #{param1}

SELECT SANCTIONS_ID, USER_ID, SANCTIONS_TYPES, SANCTIONS_START_DATE, SANCTIONS_END_DATE,
SANCTIONS_REASON, ADMIN_ACCOUNT_ID, SANCTIONS_CREATED_AT
FROM sanctions


        AND USER_ID = #{sanctionSearchDTO.userId}


        AND SANCTIONS_TYPES = #{sanctionSearchDTO.sanctionsTypes}


        AND SANCTIONS_REASON LIKE CONCAT('%', #{sanctionSearchDTO.sanctionsReason}, '%')


        AND ADMIN_ACCOUNT_ID = #{sanctionSearchDTO.adminAccountId}



        AND (
        (SANCTIONS_START_DATE BETWEEN #{sanctionSearchDTO.searchStartDate} AND #{sanctionSearchDTO.searchEndDate})
        OR (SANCTIONS_END_DATE BETWEEN #{sanctionSearchDTO.searchStartDate} AND #{sanctionSearchDTO.searchEndDate})
        OR (SANCTIONS_CREATED_AT BETWEEN #{sanctionSearchDTO.searchStartDate} AND #{sanctionSearchDTO.searchEndDate})
        )


        AND (
        SANCTIONS_START_DATE >= #{sanctionSearchDTO.searchStartDate}
        OR SANCTIONS_END_DATE >= #{sanctionSearchDTO.searchStartDate}
        OR SANCTIONS_CREATED_AT >= #{sanctionSearchDTO.searchStartDate}
        )


        AND (
        SANCTIONS_START_DATE <= #{sanctionSearchDTO.searchEndDate}
        OR SANCTIONS_END_DATE <= #{sanctionSearchDTO.searchEndDate}
        OR SANCTIONS_CREATED_AT <= #{sanctionSearchDTO.searchEndDate}
        )


ORDER BY SANCTIONS_CREATED_AT DESC
LIMIT #{searchVO.rowStart}, #{searchVO.displayRowCount}

SELECT COUNT(*)
FROM sanctions


        AND USER_ID = #{sanctionSearchDTO.userId}


        AND SANCTIONS_TYPES = #{sanctionSearchDTO.sanctionsTypes}


        AND SANCTIONS_REASON LIKE CONCAT('%', #{sanctionSearchDTO.sanctionsReason}, '%')


        AND ADMIN_ACCOUNT_ID = #{sanctionSearchDTO.adminAccountId}



        AND (
        (SANCTIONS_START_DATE BETWEEN #{sanctionSearchDTO.searchStartDate} AND #{sanctionSearchDTO.searchEndDate})
        OR (SANCTIONS_END_DATE BETWEEN #{sanctionSearchDTO.searchStartDate} AND #{sanctionSearchDTO.searchEndDate})
        OR (SANCTIONS_CREATED_AT BETWEEN #{sanctionSearchDTO.searchStartDate} AND #{sanctionSearchDTO.searchEndDate})
        )


        AND (
        SANCTIONS_START_DATE >= #{sanctionSearchDTO.searchStartDate}
        OR SANCTIONS_END_DATE >= #{sanctionSearchDTO.searchStartDate}
        OR SANCTIONS_CREATED_AT >= #{sanctionSearchDTO.searchStartDate}
        )


        AND (
        SANCTIONS_START_DATE <= #{sanctionSearchDTO.searchEndDate}
        OR SANCTIONS_END_DATE <= #{sanctionSearchDTO.searchEndDate}
        OR SANCTIONS_CREATED_AT <= #{sanctionSearchDTO.searchEndDate}
        )
